export async function getOperation(operationId){if(!transportAvailable())throw new ChrootCtlError('No supported WebUI transport is available',{code:'WEBUI_BRIDGE_UNAVAILABLE'});return appRequest('query','operations.get',{operationId:safeOperationId(operationId)});}
export async function retryOperation(operationId,handlers={}){if(!transportAvailable())throw new ChrootCtlError('No supported WebUI transport is available',{code:'WEBUI_BRIDGE_UNAVAILABLE'});await requireCapability('operations.retry','run');const args=['app','run','--request-json',bridgeRequest('operations.retry',{operationId:safeOperationId(operationId),mode:'retry'}),'--events','ndjson'];let newOperationId=null,terminal=null,bridgeFailure=null;const result=await runAllowedStream(args,line=>{let event;try{event=JSON.parse(line)}catch(_){throw new ChrootCtlError('Bridge returned invalid NDJSON',{code:'WEBUI_INVALID_JSON'})}if(event?.protocolVersion!==1)throw new ChrootCtlError('Bridge event protocol mismatch',{code:'WEBUI_CONTRACT_MISMATCH'});if(event.operationId)newOperationId=String(event.operationId);if(event.type==='bridge_error'&&event.ok===false)bridgeFailure=event;if(['operation_succeeded','operation_failed','operation_cancelled','operation_blocked'].includes(event.type))terminal=event;handlers.onEvent?.(event)});if(bridgeFailure)throw new ChrootCtlError(bridgeFailure.error?.message||'Retry request failed',{code:bridgeFailure.error?.code||'WEBUI_BACKEND_FAILURE',operationId:newOperationId});if(result.exitCode!==0||terminal?.type!=='operation_succeeded')throw new ChrootCtlError(terminal?.payload?.message||'Retry failed',{code:terminal?.payload?.code||'OPERATION_RETRY_FAILED',operationId:newOperationId,envelope:terminal});return {operationId:newOperationId,result:terminal.payload?.result??null};}


export async function listLogs(name,tail=200,level=''){if(!transportAvailable())throw new ChrootCtlError('No supported WebUI transport is available',{code:'WEBUI_BRIDGE_UNAVAILABLE'});const payload={name:safeName(name),tail:Math.max(20,Math.min(500,Number(tail)||200))};const lv=String(level||'').trim().toUpperCase();if(lv){if(!['DEBUG','INFO','WARNING','ERROR','CRITICAL'].includes(lv))throw new ChrootCtlError('Invalid log level',{code:'WEBUI_INVALID_ARGUMENT'});payload.level=lv}return appRequest('query','logs.list',payload);}
export async function doctor(name){if(!transportAvailable())throw new ChrootCtlError('No supported WebUI transport is available',{code:'WEBUI_BRIDGE_UNAVAILABLE'});return appRequest('query','system.doctor',{name:safeName(name)});}
const SERVICE_ACTIONS={start:'services.start',stop:'services.stop',restart:'services.restart',enable:'services.enable',disable:'services.disable'};
function safeService(value){const v=boundedText(value,'service',128);if(!/^[A-Za-z0-9_.@:-]+$/.test(v))throw new ChrootCtlError('Invalid service name',{code:'WEBUI_INVALID_ARGUMENT'});return v;}
function serviceMutationPayload(payload={},includeAction=true){const action=String(payload.action??'').trim().toLowerCase();if(!SERVICE_ACTIONS[action])throw new ChrootCtlError('Unsupported service action',{code:'WEBUI_INVALID_ARGUMENT'});const out={name:safeName(payload.name),service:safeService(payload.service)};if(includeAction)out.action=action;if((action==='enable'||action==='disable')&&payload.target)out.target=boundedText(payload.target,'target',128);return out;}
export async function previewServiceMutation(payload){return appRequest('preview','services.preview',serviceMutationPayload(payload,true));}
export async function runServiceMutation(payload,preview,handlers={}){if(!transportAvailable())throw new ChrootCtlError('No supported WebUI transport is available',{code:'WEBUI_BRIDGE_UNAVAILABLE'});const action=String(payload.action??'').trim().toLowerCase(),op=SERVICE_ACTIONS[action],clean=serviceMutationPayload(payload,false);if(!APP_RUN_ALLOW.has(op))throw new ChrootCtlError('Service operation is not allow-listed',{code:'WEBUI_OPERATION_NOT_ALLOWED'});await requireCapability(op,'run');for(const k of ['previewId','payloadHash','resourceRevision']){if(!preview?.[k])throw new ChrootCtlError('A fresh service preview is required',{code:'WEBUI_PREVIEW_REQUIRED'});clean[k]=boundedText(preview[k],k,256)}const args=['app','run','--request-json',bridgeRequest(op,clean),'--events','ndjson'];let operationId=null,terminal=null,bridgeFailure=null;const result=await runAllowedStream(args,line=>{let event;try{event=JSON.parse(line)}catch(_){throw new ChrootCtlError('Bridge returned invalid NDJSON',{code:'WEBUI_INVALID_JSON'})}if(event?.protocolVersion!==1)throw new ChrootCtlError('Bridge event protocol mismatch',{code:'WEBUI_CONTRACT_MISMATCH'});if(event.operationId)operationId=String(event.operationId);if(event.type==='bridge_error'&&event.ok===false)bridgeFailure=event;if(['operation_succeeded','operation_failed','operation_cancelled','operation_blocked'].includes(event.type))terminal=event;handlers.onEvent?.(event)});if(bridgeFailure)throw new ChrootCtlError(bridgeFailure.error?.message||'Service operation failed',{code:bridgeFailure.error?.code||'WEBUI_BACKEND_FAILURE',operationId,envelope:bridgeFailure});if(result.exitCode!==0||!terminal||terminal.type!=='operation_succeeded'){const p=terminal?.payload||{};throw new ChrootCtlError(p.message||'Service operation did not complete successfully',{code:p.code||'SERVICE_OPERATION_FAILED',operationId,envelope:terminal,stderr:result.stderr})}return {operationId,event:terminal,result:terminal.payload?.result??null};}
export async function listServices(name=''){if(!transportAvailable())throw new ChrootCtlError('No supported WebUI transport is available',{code:'WEBUI_BRIDGE_UNAVAILABLE'});const payload={};if(name)payload.name=safeName(name);return appRequest('query','services.list',payload);}
export async function serviceJournal(name,service,tail=120){if(!transportAvailable())throw new ChrootCtlError('No supported WebUI transport is available',{code:'WEBUI_BRIDGE_UNAVAILABLE'});const unit=boundedText(service,'service',128);if(!/^[A-Za-z0-9_.@:-]+$/.test(unit))throw new ChrootCtlError('Invalid service name',{code:'WEBUI_INVALID_ARGUMENT'});return appRequest('query','services.journal',{name:safeName(name),service:unit,tail:Math.max(1,Math.min(500,Number(tail)||120))});}
function safeNameArray(value,field='name'){const rows=Array.isArray(value)?value:[];if(rows.length>128)throw new ChrootCtlError(`Too many ${field} values`,{code:'WEBUI_INVALID_ARGUMENT'});return [...new Set(rows.map(v=>safeName(v,field)))];}
export async function previewModuleBuild(startupTargets=[]){if(!transportAvailable())throw new ChrootCtlError('No supported WebUI transport is available',{code:'WEBUI_BRIDGE_UNAVAILABLE'});return appRequest('preview','system.module_build_preview',{startupTargets:safeNameArray(startupTargets,'startup target')});}
export async function runModuleBuild(startupTargets=[],preview={},handlers={}){if(!transportAvailable())throw new ChrootCtlError('No supported WebUI transport is available',{code:'WEBUI_BRIDGE_UNAVAILABLE'});await requireCapability('system.module_build','run');const payload={startupTargets:safeNameArray(startupTargets,'startup target')};for(const k of ['previewId','payloadHash','resourceRevision'])if(preview?.[k])payload[k]=boundedText(preview[k],k,256);const args=['app','run','--request-json',bridgeRequest('system.module_build',payload),'--events','ndjson'];let operationId=null,terminal=null,bridgeFailure=null;const result=await runAllowedStream(args,line=>{let event;try{event=JSON.parse(line)}catch(_){throw new ChrootCtlError('Bridge returned invalid NDJSON',{code:'WEBUI_INVALID_JSON'})}if(event?.protocolVersion!==1)throw new ChrootCtlError('Bridge event protocol mismatch',{code:'WEBUI_CONTRACT_MISMATCH'});if(event.operationId)operationId=String(event.operationId);if(event.type==='bridge_error'&&event.ok===false)bridgeFailure=event;if(['operation_succeeded','operation_failed','operation_cancelled','operation_blocked'].includes(event.type))terminal=event;handlers.onEvent?.(event)});if(bridgeFailure)throw new ChrootCtlError(bridgeFailure.error?.message||'Module build failed',{code:bridgeFailure.error?.code||'WEBUI_BACKEND_FAILURE',operationId,envelope:bridgeFailure});if(result.exitCode!==0||terminal?.type!=='operation_succeeded')throw new ChrootCtlError(terminal?.payload?.message||'Module build failed',{code:terminal?.payload?.code||'MODULE_BUILD_FAILED',operationId,envelope:terminal,stderr:result.stderr});return {operationId,result:terminal.payload?.result??null};}


function safeSessionId(value){const v=boundedText(value,'session id',64);if(!/^cc-[a-f0-9]{16}$/.test(v))throw new ChrootCtlError('Invalid managed session ID',{code:'WEBUI_INVALID_ARGUMENT'});return v;}
async function runSessionMutation(operation,payload={}){if(!APP_RUN_ALLOW.has(operation))throw new ChrootCtlError('Session operation is not allow-listed',{code:'WEBUI_OPERATION_NOT_ALLOWED'});await requireCapability(operation,'run');const args=['app','run','--request-json',bridgeRequest(operation,payload),'--events','ndjson'];let terminal=null,bridgeFailure=null;const result=await runAllowedStream(args,line=>{let event;try{event=JSON.parse(line)}catch(_){return}if(event?.type==='bridge_error'&&event.ok===false)bridgeFailure=event;if(['operation_succeeded','operation_failed','operation_cancelled','operation_blocked'].includes(event?.type))terminal=event;});if(bridgeFailure)throw new ChrootCtlError(bridgeFailure.error?.message||'Session operation failed',{code:bridgeFailure.error?.code||'WEBUI_BACKEND_FAILURE'});if(result.exitCode!==0||!terminal||terminal.type!=='operation_succeeded')throw new ChrootCtlError(terminal?.payload?.message||'Session operation failed',{code:terminal?.payload?.code||'SESSION_OPERATION_FAILED'});return terminal.payload?.result??null;}
export async function sessionRuntime(){return appRequest('query','sessions.runtime',{});}
export async function listSessions(){return appRequest('query','sessions.list',{});}
export async function captureSession(id,lines=500,width=0,height=0){const payload={sessionId:safeSessionId(id),lines:Math.max(1,Math.min(5000,Number(lines)||500))};if(width&&height){payload.width=Math.max(20,Math.min(1000,Number(width)||120));payload.height=Math.max(5,Math.min(1000,Number(height)||40));}return appRequest('query','sessions.capture',payload);}
export async function createSession(name,username,width=120,height=40){return runSessionMutation('sessions.create',{name:safeName(name),username:safeUsername(username),width:Math.max(20,Math.min(1000,Number(width)||120)),height:Math.max(5,Math.min(1000,Number(height)||40))});}
export async function inputSession(id,text){const value=String(text??'');if(!value||new TextEncoder().encode(value).length>8192)throw new ChrootCtlError('Session input must be 1..8192 bytes',{code:'WEBUI_INVALID_ARGUMENT'});return runSessionMutation('sessions.input',{sessionId:safeSessionId(id),text:value});}
export async function detachSession(id){return runSessionMutation('sessions.detach',{sessionId:safeSessionId(id)});}
export async function killSession(id){return runSessionMutation('sessions.kill',{sessionId:safeSessionId(id)});}
